-- Simple per-part orders and returns. Existing issues/prices/history stay intact.
begin;
do $$begin if public.get_parts_return_review_version()is distinct from '20261026-parts-return-review-1'then raise exception 'Verified Parts Return Review is required.';end if;if to_regprocedure('public.get_parts_simple_version()')is not null then if public.get_parts_simple_version()is distinct from '20261026-parts-simple-1'then raise exception 'Existing simple Parts workflow needs review.';end if;end if;end;$$;
create table if not exists greenloop_private.parts_reorder_sources(request_id uuid not null,return_id uuid not null references greenloop_private.parts_flow_returns(id),quantity integer not null check(quantity>0),primary key(request_id,return_id));
alter table greenloop_private.parts_reorder_sources enable row level security;
revoke all on greenloop_private.parts_reorder_sources from public,anon,authenticated;
create or replace function greenloop_private.pp_key(p_name text)returns text language sql immutable set search_path=pg_catalog as $$select lower(regexp_replace(btrim(p_name),'\s+',' ','g'));$$;
create or replace function greenloop_private.pp_plan(p_step uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare p jsonb;item jsonb;parts jsonb:='[]';pending integer;q integer;i integer;begin
 p:=greenloop_private.ps_plan(p_step);if p is null then return null;end if;
 for item in select value from jsonb_array_elements(p->'parts')loop
 select coalesce(sum(ret.quantity),0)::integer into pending from greenloop_private.parts_flow_returns ret join public.part_issue_transactions iss on iss.id=ret.issue_id where iss.part_request_id=(item->>'request_id')::uuid and ret.status='pending';
 pending:=pending+coalesce((select sum(quantity)::integer from public.lab_part_return_requests where part_request_id=(item->>'request_id')::uuid and status='pending'),0);
 q:=greatest(0,(item->>'quantity')::integer-coalesce((item->>'returned')::integer,0)-pending);i:=greatest(0,coalesce((item->>'issued')::integer,0)-coalesce((item->>'returned')::integer,0)-pending);
 if q>0 then parts:=parts||jsonb_build_array(item||jsonb_build_object('quantity',q,'issued',i,'can_cancel',coalesce((item->>'issued')::integer,0)=0));end if;
 end loop;
 return p||jsonb_build_object('parts',parts,'part_history',p->'parts');
end;$$;
create or replace function public.get_lab_parts_plans_v3(p_step_ids uuid[])returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare result jsonb;begin perform greenloop_private.pf_cap('lab_glass','view');if p_step_ids is null or cardinality(p_step_ids)>250 then raise exception 'Select a valid technician list.'using errcode='22023';end if;select coalesce(jsonb_agg(plan),'[]')into result from(select greenloop_private.pp_plan(id)plan from(select distinct unnest(p_step_ids)id)x)y where plan is not null;return result;end;$$;
create or replace function public.add_lab_parts_v1(p_step_id uuid,p_revision integer,p_parts jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare j uuid;o greenloop_private.parts_flow_orders%rowtype;item jsonb;n text;k text;qty integer;rid uuid;ret record;need integer;take integer;seen text[]:='{}';begin
 perform greenloop_private.pf_cap('lab_glass','entry');j:=greenloop_private.pf_step(p_step_id);select *into o from greenloop_private.parts_flow_orders where job_id=j and cycle=greenloop_private.pf_cycle(j)for update;
 if p_revision is distinct from coalesce(o.revision,0)then raise exception 'Parts changed. Refresh before ordering.'using errcode='40001';end if;
 if o.id is null or o.first_issued_at is null or o.completed_at is not null then raise exception 'Use the initial parts list before the first issue.'using errcode='22023';end if;
 if p_parts is null or jsonb_typeof(p_parts)<>'array'or jsonb_array_length(p_parts)not between 1 and 100 then raise exception 'Choose at least one part.'using errcode='22023';end if;
 perform greenloop_private.pf_context(true);
 for item in select value from jsonb_array_elements(p_parts)loop
 n:=regexp_replace(btrim(item->>'name'),'\s+',' ','g');k:=greenloop_private.pp_key(n);if n is null or length(n)not between 1 and 120 or coalesce(item->>'quantity','')!~'^[0-9]{1,5}$'or k=any(seen)then raise exception 'Use one valid line per part.'using errcode='22023';end if;qty:=(item->>'quantity')::integer;if qty not between 1 and 10000 then raise exception 'Enter a positive whole quantity.'using errcode='22023';end if;seen:=array_append(seen,k);
 if exists(select 1 from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and greenloop_private.pp_key(r.part_name)=k and r.status<>'cancelled'and r.quantity_requested>r.quantity_issued)then raise exception 'This part is already ordered and waiting for issue.'using errcode='22023';end if;
 need:=case when exists(select 1 from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and greenloop_private.pp_key(r.part_name)=k and r.quantity_issued>0)then qty else 0 end;
 insert into public.job_part_requests(job_id,device_id,part_name,quantity_requested,request_source,requested_by)values(j,o.device_id,n,qty,'technician_additional',auth.uid())returning id into rid;insert into greenloop_private.parts_flow_requests values(rid,o.id);
 if need>0 then
 for ret in select rt.id,greatest(0,rt.quantity-coalesce((select sum(src.quantity)from greenloop_private.parts_reorder_sources src join public.job_part_requests used on used.id=src.request_id where src.return_id=rt.id and used.status<>'cancelled'),0))::integer available from greenloop_private.parts_flow_returns rt join public.part_issue_transactions iss on iss.id=rt.issue_id join public.job_part_requests r on r.id=iss.part_request_id where rt.order_id=o.id and rt.status in ('pending','approved')and greenloop_private.pp_key(r.part_name)=k order by rt.requested_at,rt.id loop
 take:=least(need,ret.available);if take>0 then insert into greenloop_private.parts_reorder_sources values(rid,ret.id,take);need:=need-take;end if;exit when need=0;
 end loop;
 if need>0 then raise exception 'Return the previously issued part before ordering the same part again. Return quantity must cover the new order.'using errcode='22023';end if;
 end if;
 update public.initial_qc_part_requirements set status='requested',reviewed_by=auth.uid(),reviewed_at=now()where job_id=j and greenloop_private.pp_key(part_name)=k and status in ('identified','not_required');
 insert into greenloop_private.parts_flow_audit(order_id,action,actor,details)values(o.id,'additional_part_ordered',auth.uid(),jsonb_build_object('part',n,'quantity',qty,'request_id',rid));
 end loop;
 update greenloop_private.parts_flow_orders set revision=revision+1,step_id=p_step_id,submitted_at=now(),submitted_by=auth.uid()where id=o.id;
 insert into public.device_events(device_id,job_id,event_type,event_title,event_data,actor_id)values(o.device_id,j,'additional_lab_parts','Lab / Glass ordered additional parts',jsonb_build_object('parts',p_parts),auth.uid());perform greenloop_private.pf_context(false);return greenloop_private.pp_plan(p_step_id);
end;$$;
create or replace function public.cancel_lab_part_v1(p_step_id uuid,p_revision integer,p_request_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare j uuid;o greenloop_private.parts_flow_orders%rowtype;n text;begin
 perform greenloop_private.pf_cap('lab_glass','entry');j:=greenloop_private.pf_step(p_step_id);select *into o from greenloop_private.parts_flow_orders where job_id=j and cycle=greenloop_private.pf_cycle(j)for update;if p_revision is distinct from coalesce(o.revision,0)then raise exception 'Parts changed. Refresh before removing a request.'using errcode='40001';end if;
 select r.part_name into n from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where r.id=p_request_id and m.order_id=o.id and r.quantity_issued=0 and r.status<>'cancelled'for update of r;if n is null then raise exception 'Only a part that has not been issued can be removed. Return issued parts instead.'using errcode='22023';end if;
 perform greenloop_private.pf_context(true);update public.job_part_requests set status='cancelled',updated_at=now()where id=p_request_id;update public.initial_qc_part_requirements set status='not_required',reviewed_by=auth.uid(),reviewed_at=now()where job_id=j and greenloop_private.pp_key(part_name)=greenloop_private.pp_key(n)and not exists(select 1 from public.job_part_requests r join greenloop_private.parts_flow_requests m on m.request_id=r.id where m.order_id=o.id and greenloop_private.pp_key(r.part_name)=greenloop_private.pp_key(n)and r.status<>'cancelled');update greenloop_private.parts_flow_orders set revision=revision+1 where id=o.id;insert into greenloop_private.parts_flow_audit(order_id,action,actor,details)values(o.id,'unissued_part_cancelled',auth.uid(),jsonb_build_object('part',n,'request_id',p_request_id));perform greenloop_private.pf_context(false);return greenloop_private.pp_plan(p_step_id);
end;$$;
create or replace function greenloop_private.pp_finish_return(p_return uuid,p_approve boolean)returns void language plpgsql security definer set search_path=pg_catalog,public as $$begin
 if not p_approve then update public.job_part_requests set status='cancelled',updated_at=now()where id in(select request_id from greenloop_private.parts_reorder_sources where return_id=p_return)and quantity_issued=0 and status<>'cancelled';end if;
end;$$;
-- Return reviews classify only. Lab explicitly creates every new replacement order.
do $patch$declare n text;impl text;ddl text;needle text;replacement text;begin
 foreach n in array array['issue_parts_flow_v1','review_parts_flow_return_v1']loop
 select implementation into impl from greenloop_private.office_routines r join pg_proc p on p.oid=to_regprocedure(r.identity)where p.pronamespace='public'::regnamespace and p.proname=n;if impl is null then raise exception 'Reviewed Parts routine is missing.';end if;ddl:=pg_get_functiondef(to_regprocedure(impl));
 if position('greenloop-simple-parts-202'in ddl)=0 then
 if n='issue_parts_flow_v1'then needle:='o:=greenloop_private.pf_lock(p_order_id,p_revision);';replacement:=needle||E'\n -- greenloop-simple-parts-202\n if exists(select 1 from greenloop_private.parts_reorder_sources src join greenloop_private.parts_flow_returns ret on ret.id=src.return_id where src.request_id=p_request_id and ret.status<>''approved'')then raise exception ''Review the previous part return before issuing its replacement.'' using errcode=''22023'';end if;';
 else needle:='perform greenloop_private.pf_cap(''parts'',''return'');';replacement:=needle||E'\n -- greenloop-simple-parts-202\n if p_replacement then raise exception ''Order a replacement explicitly from Lab / Glass after returning the old part.'' using errcode=''22023'';end if;';ddl:=replace(ddl,'perform greenloop_private.pf_context(false);return true;','perform greenloop_private.pp_finish_return(p_return_id,p_approve);perform greenloop_private.pf_context(false);return true;');
 end if;
 if position(needle in ddl)=0 then raise exception 'Parts source requires review: %',n;end if;execute replace(ddl,needle,replacement);update greenloop_private.office_routines set original_hash=md5(pg_get_functiondef(to_regprocedure(impl)))where implementation=impl;
 update greenloop_private.parts_return_review_installation set hash=md5(pg_get_functiondef(to_regprocedure(impl)))where kind='function'and identity=impl;
 end if;end loop;
end;$patch$;
create or replace function greenloop_private.pp_returns()returns table(id uuid,order_id uuid,legacy boolean,imei text,model text,storage_gb integer,color text,technician_name text,part_name text,quantity integer,status text,classification text,requested_at timestamptz,reviewed_at timestamptz,review_notes text)language sql stable security definer set search_path=pg_catalog,public as $$
 select ret.id,o.id,false,d.imei_1,d.model,d.storage_gb,d.color,st.assigned_technician_name,r.part_name,ret.quantity,ret.status,ret.classification,ret.requested_at,ret.reviewed_at,ret.review_notes from greenloop_private.parts_flow_returns ret join greenloop_private.parts_flow_orders o on o.id=ret.order_id join public.jobs j on j.id=o.job_id and j.deleted_at is null join public.devices d on d.id=o.device_id and d.deleted_at is null join public.part_issue_transactions iss on iss.id=ret.issue_id join public.job_part_requests r on r.id=iss.part_request_id left join public.job_work_order_steps st on st.id=o.step_id
 union all
 select ret.id,null::uuid,true,d.imei_1,d.model,d.storage_gb,d.color,st.assigned_technician_name,ret.part_name,ret.quantity,ret.status,case when ret.status='approved'then ret.return_reason end,ret.requested_at,ret.reviewed_at,ret.review_notes from public.lab_part_return_requests ret join public.jobs j on j.id=ret.job_id and j.deleted_at is null join public.devices d on d.id=ret.device_id and d.deleted_at is null left join public.job_work_order_steps st on st.id=ret.work_order_step_id where not exists(select 1 from greenloop_private.parts_flow_returns pr join public.part_issue_transactions iss on iss.id=pr.issue_id where iss.part_request_id=ret.part_request_id and pr.requested_at=ret.requested_at and pr.quantity=ret.quantity and pr.notes like 'Existing return: %');
$$;
create or replace function public.get_parts_returns_v1(p_filters jsonb default '{}',p_category text default 'pending',p_offset integer default 0,p_limit integer default 50,p_sort_key text default 'requested_at',p_sort_direction text default 'desc')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare f date;t date;s text;result jsonb;begin
 perform greenloop_private.pf_cap('parts','view');if jsonb_typeof(p_filters)is distinct from 'object'or exists(select 1 from jsonb_object_keys(p_filters)k where k not in ('_search','_from','_to'))or p_category is null or p_category not in ('pending','damaged','faulty','not_needed','other')or p_offset is null or p_offset<0 or p_limit is null or p_limit not between 1 and 100 or p_sort_key is null or p_sort_key not in ('requested_at','imei','model','part_name','quantity')or p_sort_direction is null or p_sort_direction not in ('asc','desc')then raise exception 'Select valid return filters.'using errcode='22023';end if;
 if p_filters<>'{}'then perform greenloop_private.pf_cap('parts','search');end if;if p_sort_key<>'requested_at'or p_sort_direction<>'desc'then perform greenloop_private.pf_cap('parts','sort');end if;f:=nullif(p_filters->>'_from','')::date;t:=nullif(p_filters->>'_to','')::date;s:=lower(btrim(coalesce(p_filters->>'_search','')));if f>t or length(s)>120 then raise exception 'Select valid dates or search.'using errcode='22023';end if;
 with base as materialized(select *from greenloop_private.pp_returns()where(f is null or(requested_at at time zone 'Asia/Dubai')::date>=f)and(t is null or(requested_at at time zone 'Asia/Dubai')::date<=t)and(s=''or strpos(lower(concat_ws(' ',imei,model,storage_gb,color,technician_name,part_name,review_notes)),s)>0)),q as materialized(select *from base where case when p_category='pending'then status='pending'else status='approved'and classification=p_category end),page as(select *from q order by case when p_sort_key='requested_at'and p_sort_direction='asc'then requested_at end asc,case when p_sort_key='requested_at'and p_sort_direction='desc'then requested_at end desc,case when p_sort_key='quantity'and p_sort_direction='asc'then quantity end asc,case when p_sort_key='quantity'and p_sort_direction='desc'then quantity end desc,case when p_sort_direction='asc'then case p_sort_key when 'imei'then imei when 'model'then model when 'part_name'then part_name end end asc,case when p_sort_direction='desc'then case p_sort_key when 'imei'then imei when 'model'then model when 'part_name'then part_name end end desc,id offset p_offset limit p_limit)
 select jsonb_build_object('total',(select count(*)from q),'rows',coalesce((select jsonb_agg(to_jsonb(p))from page p),'[]'),'counts',(select jsonb_build_object('pending',count(*)filter(where status='pending'),'damaged',coalesce(sum(quantity)filter(where status='approved'and classification='damaged'),0),'faulty',coalesce(sum(quantity)filter(where status='approved'and classification='faulty'),0),'not_needed',coalesce(sum(quantity)filter(where status='approved'and classification='not_needed'),0),'other',coalesce(sum(quantity)filter(where status='approved'and classification='other'),0))from base))into result;return result;
end;$$;

insert into greenloop_private.capability_rpc_rules values('get_lab_parts_plans_v3','{"page":"lab_glass","capability":"view","read":true}'::jsonb)on conflict(rpc_name)do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('add_lab_parts_v1','{"page":"lab_glass","capability":"entry"}'::jsonb)on conflict(rpc_name)do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('cancel_lab_part_v1','{"page":"lab_glass","capability":"entry"}'::jsonb)on conflict(rpc_name)do update set rule=excluded.rule;
insert into greenloop_private.capability_rpc_rules values('get_parts_returns_v1','{"page":"parts","capability":"view","read":true}'::jsonb)on conflict(rpc_name)do update set rule=excluded.rule;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)from greenloop_private.capability_rpc_rules r)where identity='rules';
do $wrap$declare f record;impl text;impl_identity text;args text;body text;begin
 for f in select p.*,pg_get_functiondef(p.oid)ddl,p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('get_lab_parts_plans_v3','add_lab_parts_v1','cancel_lab_part_v1','get_parts_returns_v1')loop
 impl:='office_impl_'||f.oid;execute regexp_replace(f.ddl,'FUNCTION public\.'||f.proname||'\(','FUNCTION greenloop_private.'||impl||'(');impl_identity:='greenloop_private.'||impl||'('||oidvectortypes(f.proargtypes)||')';execute format('revoke all on function %s from public,anon,authenticated',impl_identity);select coalesce(string_agg('$'||i,','order by i),'')into args from generate_series(1,f.pronargs)i;
 body:=E'begin\n -- greenloop-office-wrapper-196\n perform greenloop_private.require_office_network();\n return greenloop_private.'||impl||'('||args||E');\nend;';execute format('create or replace function public.%I(%s)returns %s language plpgsql %s security definer set search_path=pg_catalog,public as %L',f.proname,pg_get_function_arguments(f.oid),pg_get_function_result(f.oid),case f.provolatile when 's'then 'stable'else 'volatile'end,body);execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to authenticated',f.signature);insert into greenloop_private.office_routines values(f.signature,impl_identity,md5(pg_get_functiondef(impl_identity::regprocedure)),md5(pg_get_functiondef(f.oid)))on conflict(identity)do update set implementation=excluded.implementation,original_hash=excluded.original_hash,wrapped_hash=excluded.wrapped_hash;
 end loop;for f in select p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='greenloop_private'::regnamespace and p.proname like 'pp_%'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);end loop;
end;$wrap$;
create table if not exists greenloop_private.parts_simple_installation(identity text primary key,hash text not null);
alter table greenloop_private.parts_simple_installation enable row level security;revoke all on greenloop_private.parts_simple_installation from public,anon,authenticated;
insert into greenloop_private.parts_simple_installation select p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid))from pg_proc p where(p.pronamespace='public'::regnamespace and p.proname in ('get_lab_parts_plans_v3','add_lab_parts_v1','cancel_lab_part_v1','get_parts_returns_v1'))or(p.pronamespace='greenloop_private'::regnamespace and p.proname like 'pp_%')or p.oid in(select to_regprocedure(r.implementation)from greenloop_private.office_routines r join pg_proc pub on pub.oid=to_regprocedure(r.identity)where pub.proname in ('issue_parts_flow_v1','review_parts_flow_return_v1'))on conflict(identity)do update set hash=excluded.hash;
create or replace function public.get_parts_simple_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_parts_return_review_version()='20261026-parts-return-review-1'
 and(select count(*)=10 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.parts_simple_installation)
 and not exists(select 1 from unnest(array['parts_simple_installation','parts_reorder_sources'])t where has_table_privilege('authenticated','greenloop_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')or has_table_privilege('anon','greenloop_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'))
 and not exists(select 1 from greenloop_private.parts_simple_installation where identity like 'greenloop_private.%'and(has_function_privilege('authenticated',to_regprocedure(identity),'EXECUTE')or has_function_privilege('anon',to_regprocedure(identity),'EXECUTE')))
 then '20261026-parts-simple-1'end;$$;
revoke all on function public.get_parts_simple_version()from public;grant execute on function public.get_parts_simple_version()to anon,authenticated;
do $$begin if public.get_parts_simple_version()is distinct from '20261026-parts-simple-1'then raise exception 'Simple Parts workflow verification failed.';end if;end;$$;
notify pgrst,'reload schema';commit;
select public.get_parts_simple_version()as installed_parts_simple_version;
